__device__ __forceinline__ void warp_max_with_index(
    float& value, int& index, unsigned mask)
{
    for (int offset = 16; offset > 0; offset >>= 1) {
        const float other_value = __shfl_down_sync(mask, value, offset);
        const int other_index = __shfl_down_sync(mask, index, offset);
        const bool value_nan = isnan(value);
        const bool other_nan = isnan(other_value);
        if (value_nan) {
            if (other_nan && other_index < index) {
                value = other_value;
                index = other_index;
            }
        } else if (other_nan ||
                   other_value > value ||
                   (other_value == value && other_index < index)) {
            value = other_value;
            index = other_index;
        }
    }
}
__global__ void cute_max_dim1_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int B,
    int D1,
    int D2)
{
    const int batch = blockIdx.y;
    if (batch >= B) {
        return;
    }
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    const int col_step = static_cast<int>(gridDim.x) * 8;
    for (int col = blockIdx.x * 8 + warp;
         col < D2;
         col += col_step) {
        float best = -CUDART_INF_F;
        int best_k = D1;
        for (int k = lane; k < D1; k += 32) {
            const float value =
                __ldg(x + (static_cast<long long>(batch) * D1 + k) * D2 + col);
            if (isnan(value)) {
                if (!isnan(best) || k < best_k) {
                    best = value;
                    best_k = k;
                }
            } else if (!isnan(best) &&
                       (value > best ||
                        (value == best && k < best_k))) {
                best = value;
                best_k = k;
            }
        }
        warp_max_with_index(best, best_k, 0xffffffffu);
        if (lane == 0) {
            out[static_cast<long long>(batch) * D2 + col] = best;
        }
    }
